import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

// Single fused elementwise Tanh kernel (fast-math optimized).
// tanh(x) = sign(x) * (1 - e) / (1 + e), e = __expf(-2*|x|) in (0, 1]:
// numerically stable, branch-free, low instruction count. float4
// vectorized loads/stores with evict-first streaming hints (__ldcs/
// __stcs) keep L2 clean for this purely streaming, zero-reuse kernel.
// Optimization (new): cut register pressure to lift occupancy.
// Profiler shows ~90% DRAM throughput but only ~79% achieved
// occupancy: the previous 40-register build keeps just 6 blocks
// (1536 threads) resident per SM, capping warps at 75%. This version
// keeps the x4-unrolled grid-stride loop (four independent 16B
// streaming loads in flight per warp) but switches indexing to
// 32-bit integers on the common path and drops precomputed stride
// multiples so the compiler stays under a 32-register budget;
// __launch_bounds__(256, 8) then allows 8 resident blocks = 2048
// threads per SM (full occupancy). More resident warps x the same
// 4 outstanding loads each increases total bytes in flight per SM.
__device__ __forceinline__ float fast_tanhf(float x) {
    const float e = __expf(-2.0f * fabsf(x));  // in (0, 1], never overflows
    const float t = __fdividef(1.0f - e, 1.0f + e);
    return copysignf(t, x);
}
template <typename index_t>
__global__ void __launch_bounds__(256, 8) tanh_kernel(
                            const float* __restrict__ in,
                            float* __restrict__ out,
                            const index_t n) {
    const index_t n4 = n >> 2;  // number of full float4 groups
    const index_t tid = (index_t)blockIdx.x * blockDim.x + threadIdx.x;
    const index_t stride = (index_t)gridDim.x * blockDim.x;
    const float4* in4  = reinterpret_cast<const float4*>(in);
    float4*       out4 = reinterpret_cast<float4*>(out);
    index_t idx = tid;
    // Unrolled main loop: four independent float4 streaming loads are
    // issued back-to-back before any result is consumed. Stride
    // multiples are recomputed by the compiler (cheap adds) instead of
      // being kept in dedicated registers, keeping register pressure
    // under the 32-register budget needed for 8 resident blocks/SM.
    for (; idx + 3 * stride < n4; idx += stride << 2) {
        float4 a = __ldcs(&in4[idx]);
        float4 b = __ldcs(&in4[idx + stride]);
        float4 c = __ldcs(&in4[idx + 2 * stride]);
        float4 d = __ldcs(&in4[idx + 3 * stride]);
        a.x = fast_tanhf(a.x);
        a.y = fast_tanhf(a.y);
        a.z = fast_tanhf(a.z);
        a.w = fast_tanhf(a.w);
        b.x = fast_tanhf(b.x);
        b.y = fast_tanhf(b.y);
        b.z = fast_tanhf(b.z);
        b.w = fast_tanhf(b.w);
        c.x = fast_tanhf(c.x);
        c.y = fast_tanhf(c.y);
        c.z = fast_tanhf(c.z);
        c.w = fast_tanhf(c.w);
        d.x = fast_tanhf(d.x);
        d.y = fast_tanhf(d.y);
        d.z = fast_tanhf(d.z);
        d.w = fast_tanhf(d.w);
        __stcs(&out4[idx], a);
        __stcs(&out4[idx + stride], b);
        __stcs(&out4[idx + 2 * stride], c);
        __stcs(&out4[idx + 3 * stride], d);
    }
    // Cleanup loop for the remaining float4 groups.
    for (; idx < n4; idx += stride) {
        float4 a = __ldcs(&in4[idx]);
        a.x = fast_tanhf(a.x);
        a.y = fast_tanhf(a.y);
        a.z = fast_tanhf(a.z);
        a.w = fast_tanhf(a.w);
        __stcs(&out4[idx], a);
    }
    const index_t tail_start = n4 << 2;
    if (tid < n - tail_start) {
        const index_t i = tail_start + tid;
        __stcs(&out[i], fast_tanhf(__ldcs(&in[i])));
    }
}

torch::Tensor tanh_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");

    auto out = torch::empty_like(x);
    const long n = x.numel();
    if (n == 0) return out;

    // Launch config: persistent grid sized to exactly fill the device
    // under __launch_bounds__(256, 8) (SMs * 8 blocks of 256 threads =
    // 2048 resident threads per SM, i.e. full occupancy). The tighter
    // register budget is met by using 32-bit indexing on the common
    // path (numel < 2^31); a 64-bit instantiation of the same template
    // keeps arbitrarily large tensors correct. The x4-unrolled
    // grid-stride loop covers all float4 groups with a single kernel
    // launch; memory access pattern, vectorization, and semantics are
    // unchanged.
    const int threads = 256;
    int num_sms = 0;
    cudaDeviceGetAttribute(&num_sms, cudaDevAttrMultiProcessorCount,
                           x.get_device());
    const long max_blocks = (long)num_sms * 8L;
    if (n <= 2147483647L) {
        const int n4 = (int)((n + 3) >> 2);
        long blocks = (n4 + threads - 1) / threads;
        if (blocks > max_blocks) blocks = max_blocks;
        tanh_kernel<int><<<(int)blocks, threads>>>(
            x.data_ptr<float>(),
            out.data_ptr<float>(),
            (int)n);
    } else {
        const long n4 = (n + 3) >> 2;
        long blocks = (n4 + threads - 1) / threads;
        if (blocks > max_blocks) blocks = max_blocks;
        tanh_kernel<long><<<(int)blocks, threads>>>(
            x.data_ptr<float>(),
            out.data_ptr<float>(),
            n);
    }

    return out;
}
"""

cpp_src = "torch::Tensor tanh_forward(torch::Tensor x);"

_tanh_mod = load_inline(
    name="tanh_cuda_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["tanh_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Tanh activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _tanh_mod.tanh_forward(x)

